pub fn isLeapYear(year: u16) bool {
        return ((((year % 4) == 0) and ((year % 100) != 0)) or ((year % 400) == 0));
}

pub fn daysInMonth(year: u16, month: u8) u8 {
        const days: [12]u8 = .{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        if (((month == 2) and isLeapYear(year))) {
            return 29;
        }
        return days[@as(usize, @intCast((month - 1)))];
}

pub fn gregorianDate(days: i32) Date {
        var d = days;
        _ = &d;
        var y: u16 = 1970;
        _ = &y;
        while ((d >= (365 + (if (comptime @typeInfo(@TypeOf(@intFromBool(isLeapYear(y)))) == .@"enum") cp_cast_int(u16, @intFromEnum(@intFromBool(isLeapYear(y)))) else cp_cast_int(u16, @intFromBool(isLeapYear(y))))))) {
            d = (d - (365 + (if (comptime @typeInfo(@TypeOf(@intFromBool(isLeapYear(y)))) == .@"enum") cp_cast_int(u16, @intFromEnum(@intFromBool(isLeapYear(y)))) else cp_cast_int(u16, @intFromBool(isLeapYear(y))))));
            y = (y + 1);
        }
        var m: u8 = 1;
        _ = &m;
        while ((d >= daysInMonth(y, m))) {
            d = (d - daysInMonth(y, m));
            m = (m + 1);
        }
        return Date{ .year = y, .month = m, .day = @intCast((d + 1)) };
}

pub fn fieldTypeFromJS(globalObject: *JSC.JSGlobalObject, value: JSValue, unsigned: *bool) bun.JSError!FieldType {
        if (value.isEmptyOrUndefinedOrNull()) {
            return error.MYSQL_TYPE_NULL;
        }
        if (value.isCell()) {
            const tag = value.jsType();
            if (tag.isStringLike()) {
                return error.MYSQL_TYPE_STRING;
            }
            if ((tag == .JSDate)) {
                return error.MYSQL_TYPE_DATETIME;
            }
            if (tag.isTypedArrayOrArrayBuffer()) {
                return error.MYSQL_TYPE_BLOB;
            }
            if ((tag == .HeapBigInt)) {
                if (value.isBigIntInInt64Range(std.math.minInt(i64), std.math.maxInt(i64))) {
                    return error.MYSQL_TYPE_LONGLONG;
                }
                if (value.isBigIntInUInt64Range(0, std.math.maxInt(u64))) {
                    {
                        unsigned.* = true;
                    }
                    return error.MYSQL_TYPE_LONGLONG;
                }
                return globalObject.ERR(.OUT_OF_RANGE, "The value is out of range. It must be >= {d} and <= {d}.", .{ std.math.minInt(i64), std.math.maxInt(u64) }).throw();
            }
            if (globalObject.hasException()) {
                return error.JSError;
            }
            if ((tag == .NumberObject)) {
                return globalObject.throwInvalidArguments("Cannot bind NumberObject to query parameter. Use a primitive number instead.", .{});
            }
            if ((tag == .BooleanObject)) {
                return globalObject.throwInvalidArguments("Cannot bind BooleanObject to query parameter. Use a primitive boolean instead.", .{});
            }
            if ((!tag.isIndexable())) {
                return globalObject.throwInvalidArguments("Cannot bind this type to query parameter", .{});
            }
            if (tag.isObject()) {
                return error.MYSQL_TYPE_JSON;
            }
        }
        if (value.isAnyInt()) {
            const int = value.toInt64();
            if ((int >= 0)) {
                if ((int <= std.math.maxInt(i32))) {
                    return error.MYSQL_TYPE_LONG;
                }
                if ((int <= std.math.maxInt(u32))) {
                    {
                        unsigned.* = true;
                    }
                    return error.MYSQL_TYPE_LONG;
                }
                if ((int >= std.math.maxInt(i64))) {
                    {
                        unsigned.* = true;
                    }
                    return error.MYSQL_TYPE_LONGLONG;
                }
                return error.MYSQL_TYPE_LONGLONG;
            }
            if ((int >= std.math.minInt(i32))) {
                return error.MYSQL_TYPE_LONG;
            }
            return error.MYSQL_TYPE_LONGLONG;
        }
        if (value.isNumber()) {
            return error.MYSQL_TYPE_DOUBLE;
        }
        if (value.isBoolean()) {
            return error.MYSQL_TYPE_TINY;
        }
        return error.MYSQL_TYPE_VARCHAR;
}
